[CmdletBinding()]
param([Parameter(Mandatory)][string]$ExecutablePath,[Parameter(Mandatory)][string]$OutputDirectory,[Parameter(Mandatory)][string]$ReportPath,[ValidateNotNullOrEmpty()][string[]]$CaseFilter=@('*'),[switch]$Large,[ValidateRange(32769,65535)][int]$LargeFileCount=32769,[string]$AssemblyPath,[string]$ExpectedAssemblySha256)
$ErrorActionPreference='Stop'
# 想定する失敗: private file journal/PIDL/stage生成、dry-runの変更、サイズ超過以外での永久削除、
# nativeID/ACL/全stream/link関係の欠落、衝突上書き、preflight一部削除、並列入力順の破損、
# サイズ超過後の誤った成功やBin残存、混合結果の取り違え、リンク先や別名の破損、
# 予算によるBin消費、古いfile restore入口/MCPtool残存、曖昧結果の自動再送、
# 独立sparseを含む複数巨大rootの共有別名で片方だけ削除・結果順の破損・外部別名の内容/ID/ACL破損・回収不能。
$repo=[IO.Path]::GetFullPath((Split-Path $PSScriptRoot -Parent))
. (Join-Path $PSScriptRoot 'Verification-Common.ps1')
foreach($path in @($ExecutablePath,$OutputDirectory,$ReportPath)){if(![IO.Path]::IsPathFullyQualified($path)){throw 'Absolute paths required'}}
foreach($path in @($OutputDirectory,$ReportPath)){Assert-VerificationDestination $path @($repo,(Join-Path $env:USERPROFILE '.codex'));if(![IO.Path]::GetPathRoot($path).Equals('D:\',[StringComparison]::OrdinalIgnoreCase)){throw 'External D output required'};if(Test-Path -LiteralPath $path){throw 'Unused output/report required'};if(![IO.Directory]::Exists([IO.Path]::GetDirectoryName($path))){throw 'Output parent must exist'}}
if(![IO.File]::Exists($ExecutablePath)){throw 'Executable missing'}
if([bool]$AssemblyPath-ne[bool]$ExpectedAssemblySha256){throw 'AssemblyPath and ExpectedAssemblySha256 must be supplied together'}
if($AssemblyPath){if(![IO.Path]::IsPathFullyQualified($AssemblyPath)-or![IO.File]::Exists($AssemblyPath)){throw 'Absolute candidate assembly required'};if((Get-FileHash -LiteralPath $AssemblyPath).Hash-cne$ExpectedAssemblySha256){throw 'Candidate assembly hash mismatch'}}
$null=[IO.Directory]::CreateDirectory($OutputDirectory);$script:temp=Join-Path $OutputDirectory 'temp';$null=[IO.Directory]::CreateDirectory($script:temp)
$oldTemp=$env:TEMP;$oldTmp=$env:TMP;$env:TEMP=$script:temp;$env:TMP=$script:temp
$helperFiles=@('NativeShellFixture.cs','FixtureNative.cs','OwnedBinLocator.cs')|ForEach-Object {Join-Path (Join-Path $PSScriptRoot 'recordless-e2e') $_}
$common=Join-Path $PSScriptRoot 'recordless-e2e/Common.ps1';. $common
$rendezvousHost=Join-Path $PSScriptRoot 'recordless-e2e/OversizeBatchRendezvousHost.ps1';$initialSourceHash=(Get-FileHash $PSCommandPath).Hash;$initialSources=@(@($PSCommandPath,$common,$rendezvousHost,(Join-Path $PSScriptRoot 'recordless-e2e/SparseFixture.cs'))+$helperFiles|ForEach-Object {@{path=$_;sha256=(Get-FileHash $_).Hash}});$results=[Collections.Generic.List[object]]::new();$script:commands=[Collections.Generic.List[object]]::new();$catalog=[Collections.Generic.List[string]]::new();$excluded=[Collections.Generic.List[string]]::new()
function Case-R([string]$Name,[scriptblock]$Body,[switch]$RequiresLarge,[switch]$RequiresAssembly){$catalog.Add($Name);if(($RequiresLarge-and!$Large)-or($RequiresAssembly-and!$AssemblyPath)-or!@($CaseFilter|Where-Object {$Name-like$_}).Count){$excluded.Add($Name);return};$script:observed=@{};$script:skipReason=$null;$clock=[Diagnostics.Stopwatch]::StartNew();try{& $Body;$results.Add(@{name=$Name;passed=$(if($script:skipReason){$null}else{$true});skipped=[bool]$script:skipReason;note=$script:skipReason;observed=$script:observed;elapsedMs=$clock.ElapsedMilliseconds})}catch{$results.Add(@{name=$Name;passed=$false;error=$_.Exception.Message;stack=$_.ScriptStackTrace;observed=$script:observed;elapsedMs=$clock.ElapsedMilliseconds})}}
function Initialize-SparseR {
 if (!('PrunletSparseE2E' -as [type])) { Add-Type -Path (Join-Path $PSScriptRoot 'recordless-e2e/SparseFixture.cs') }
}
function New-OversizeR([string]$Path){
 $prefix=$utf8.GetBytes('owned sparse prefix; allocated tails must stay zero');$logical=[long]1099511627776;$script:observed.sparsePath=$Path
 $stream=[IO.FileStream]::new($Path,[IO.FileMode]::CreateNew,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)
 try{[PrunletSparseE2E]::MakeSparse($stream.SafeFileHandle);$stream.Write($prefix,0,$prefix.Length);$stream.SetLength($logical);$stream.Flush($true)}finally{$stream.Dispose()}
 $proof=[PrunletSparseE2E]::CaptureProof($Path);$item=@{path=$Path;prefix=$prefix;logical=$logical;proof=$proof;prior=[string[]]@([Prunlet.RecordlessE2E.OwnedBinLocator]::FindIdentity($proof.Id)|ForEach-Object Pidl)}
 $script:observed.sparseCreation=$proof;return $item
}
function Assert-NoNewBinR([string]$Id,[string[]]$Prior){$new=@([Prunlet.RecordlessE2E.OwnedBinLocator]::FindIdentity($Id)|Where-Object {$_.Pidl-notin$Prior});Assert-R ($new.Count-eq0) ('Unexpected new Bin item for native identity '+$Id)}
function Assert-SparseProofR($Expected,$Actual,[int]$Links){foreach($field in @('Id','SecurityBase64','Attributes','Length')){Assert-R ($Expected.$field-ceq$Actual.$field) ('Sparse '+$field+' changed')};Assert-R ($Actual.NumberOfLinks-eq$Links) 'Sparse link count changed';Assert-R ($Actual.AllocationSize-le1MB-and$Actual.CompressedSize-le1MB) 'Sparse allocation grew unexpectedly'}
function Finish-OversizeR($Scope,$Sparse,[string]$Root,[string]$RootId,[string[]]$RootPrior,[string]$Alias='',$Members=@()){
 # 誤ってゴミ箱に入った場合も、今回のnative IDと先行PIDLを照合してからだけ復元する。
 if(!(Test-Path -LiteralPath $Root)){$new=@([Prunlet.RecordlessE2E.OwnedBinLocator]::FindIdentity($RootId)|Where-Object {$_.Pidl-notin$RootPrior});if($new.Count-eq1){$null=[Prunlet.RecordlessE2E.FixtureNative]::RestoreOwned($new[0].Pidl,$new[0].PhysicalPath,$RootId,$Root,$Scope.files)}elseif($new.Count-gt1){throw 'Multiple unexpected owned Bin entries; fixtures retained'}}
 $issues=[Collections.Generic.List[string]]::new();$reconciled=[Collections.Generic.List[object]]::new();$script:observed.childReconciliation=$reconciled;$sparseIssue=$false
 if($Members.Count){
  $rootExists=[IO.Directory]::Exists($Root);if($rootExists){Assert-R ([Prunlet.RecordlessE2E.FixtureNative]::Identity($Root)-ceq$RootId) 'Directory identity changed; children retained'}
  foreach($member in $Members){
   $state=@{path=$member.path;id=$member.id;kind=$member.kind};$reconciled.Add($state)
   try{
    $found=@([Prunlet.RecordlessE2E.OwnedBinLocator]::FindIdentity($member.id)|Where-Object {$_.Pidl-notin$member.prior});$state.newBinItems=$found;$present=Test-Path -LiteralPath $member.path;$state.originalPresent=$present
    if($found.Count-gt1){throw 'Multiple new Bin items; retained'}
    if($found.Count-eq1){
     if($present){throw 'Original and new Bin item both exist; retained'}
     if(!$rootExists){throw 'Original parent is absent; Bin item retained'}
     $null=[Prunlet.RecordlessE2E.FixtureNative]::RestoreOwned($found[0].Pidl,$found[0].PhysicalPath,$member.id,$member.path,$Scope.files);$state.restored=$true;$present=$true
    }
    if($present){Assert-R ([Prunlet.RecordlessE2E.FixtureNative]::Identity($member.path)-ceq$member.id) 'Original native identity differs; retained';if($member.before){$null=Assert-SnapshotR $member.path $member.before -WindowsInheritance};$state.retainedAtOriginal=$member.path}
    elseif($rootExists){throw 'Child missing from original and Bin; inspect fixture'}
    else{$state.absentWithRoot=$true}
   }catch{$state.error=$_.Exception.ToString();$issues.Add(($member.path+': '+$state.error));if($member.kind-ceq'sparse'){$sparseIssue=$true}}
  }
 }
 $path=if([IO.File]::Exists($Sparse.path)){$Sparse.path}elseif($Alias-and[IO.File]::Exists($Alias)){$Alias}else{$null}
 if($path-and!$sparseIssue){
  $current=[PrunletSparseE2E]::CaptureProof($path);Assert-SparseProofR $Sparse.proof $current 1
  $tiny=[PrunletSparseE2E]::RestoreTiny($path,$Sparse.proof.Id,$Sparse.proof.SecurityBase64,[int]$Sparse.proof.Attributes,$Sparse.logical,$Sparse.prefix,[ulong]1048576);$script:observed.sparseFinalizer=$tiny;Assert-R $tiny.Success ('Sparse fixture retained: '+$tiny.Error)
  $priorTiny=[string[]]@([Prunlet.RecordlessE2E.OwnedBinLocator]::FindIdentity($Sparse.proof.Id)|ForEach-Object Pidl);$cleanup=Delete-R $Scope @($path);$script:observed.sparseCleanup=$cleanup;Assert-WireR $cleanup @($path) @('recycled');Assert-R ($cleanup.exitCode-eq0) 'Tiny fixture cleanup failed';$script:observed.cleanupBin=[Prunlet.RecordlessE2E.OwnedBinLocator]::FindNew($Sparse.proof.Id,$priorTiny)
 }
 if($issues.Count){throw ('Oversized fixture reconciliation failed: '+($issues-join'; '))}
}
function Test-OversizeR([string]$Mode){
 Initialize-SparseR;$s=New-ScopeR ('oversize-'+$Mode);$tree=$Mode-in@('tree','mcp-tree');$hardlink=$Mode-ceq'hardlink';$mcp=$Mode-in@('mcp','mcp-tree')
 $root=if($tree){Join-Path $s.files 'tree'}else{Join-Path $s.files 'huge-sparse'};if($tree){$null=[IO.Directory]::CreateDirectory($root)}
 $path=if($tree){Join-Path $root 'huge-sparse'}else{$root};$sparse=New-OversizeR $path;$alias='';$session=$null;$ordinary=$null;$normalBefore=$null;$normalPrior=@();$members=[Collections.Generic.List[object]]::new();if($tree){$members.Add(@{path=$path;id=$sparse.proof.Id;prior=$sparse.prior;kind='sparse';before=$null})};$rootId=if($tree){[Prunlet.RecordlessE2E.FixtureNative]::Identity($root)}else{$sparse.proof.Id};$rootPrior=[string[]]@([Prunlet.RecordlessE2E.OwnedBinLocator]::FindIdentity($rootId)|ForEach-Object Pidl)
 try{
  Assert-R ($sparse.proof.Length-eq$sparse.logical-and$sparse.proof.NumberOfLinks-eq1-and[PrunletSparseE2E]::Allocation($path)-le1MB) 'Sparse fixture shape or allocation invalid'
  if($hardlink){$alias=Join-Path $s.files 'surviving-alias';[Prunlet.RecordlessE2E.FixtureNative]::CreateHardlink($alias,$path);$sparse.proof=[PrunletSparseE2E]::CaptureProof($path);Assert-R ($sparse.proof.NumberOfLinks-eq2) 'Hardlink fixture not established'}
  elseif($tree){$ordinary=File-R $s 'tree/ordinary';$normalBefore=Snapshot-R $ordinary;$normalPrior=Before-BinR $normalBefore;$members.Add(@{path=$ordinary;id=$normalBefore[0].Id;prior=$normalPrior;kind='ordinary';before=$normalBefore});$target=File-R $s 'outside/target';$targetRoot=Split-Path $target;$targetBefore=Snapshot-R $targetRoot;$link=Join-Path $root 'outside-link';$null=New-Item -ItemType Junction -Path $link -Target $targetRoot;$linkBefore=Snapshot-R $link;$linkPrior=Before-BinR $linkBefore;$members.Add(@{path=$link;id=$linkBefore[0].Id;prior=$linkPrior;kind='junction';before=$linkBefore})}
  else{$ordinary=File-R $s 'ordinary';$normalBefore=Snapshot-R $ordinary;$normalPrior=Before-BinR $normalBefore}
  $paths=if($ordinary-and!$tree){@($ordinary,$root)}else{@($root)};$statuses=if($ordinary-and!$tree){@('recycled','permanently_deleted')}else{@('permanently_deleted')};$dryStatuses=@($paths|ForEach-Object {'would_recycle'})
  if($mcp){$session=Open-McpR $s;Init-McpR $session;$dry=Call-McpR $session 2 'delete_files' @{paths=@($paths);dryRun=$true;recursive=[bool]$tree};$script:observed.dry=$dry;Assert-R (!$dry.failed) 'MCP dry-run failed'}else{$dry=Delete-R $s $paths -Recursive:$tree -DryRun;Assert-R ($dry.exitCode-eq0) 'CLI dry-run failed'}
  $script:observed.dry=$dry;Assert-WireR $dry $paths $dryStatuses $true;Assert-R (@($dry.json.warnings|Where-Object {$_-match'(?i)dry.run'-and$_-match'(?i)permanent'}).Count-gt0) 'Dry-run did not warn that permanent deletion cannot be determined';$after=[PrunletSparseE2E]::CaptureProof($path);Assert-SparseProofR $sparse.proof $after $(if($hardlink){2}else{1});Assert-NoNewBinR $sparse.proof.Id $sparse.prior;if($ordinary){$null=Assert-SnapshotR $ordinary $normalBefore;Assert-NoNewBinR $normalBefore[0].Id $normalPrior};if($tree){$null=Assert-SnapshotR $targetRoot $targetBefore;$null=Assert-SnapshotR $link $linkBefore;Assert-NoNewBinR $linkBefore[0].Id $linkPrior};if($hardlink){$afterAlias=[PrunletSparseE2E]::CaptureProof($alias);Assert-SparseProofR $sparse.proof $afterAlias 2}
  if($mcp){$result=Call-McpR $session 3 'delete_files' @{paths=@($paths);recursive=[bool]$tree};$script:observed.delete=$result;Assert-R (!$result.failed) 'MCP delete failed'}else{$result=Delete-R $s $paths -Recursive:$tree;Assert-R ($result.exitCode-eq0) 'CLI delete failed'}
  $script:observed.delete=$result;Assert-WireR $result $paths $statuses;Assert-R (!(Test-Path -LiteralPath $root)) 'Oversized input remained';Assert-NoNewBinR $rootId $rootPrior;Assert-NoNewBinR $sparse.proof.Id $sparse.prior
  if($tree){Assert-NoNewBinR $normalBefore[0].Id $normalPrior;Assert-NoNewBinR $linkBefore[0].Id $linkPrior;$null=Assert-SnapshotR $targetRoot $targetBefore}
  elseif($hardlink){$survivor=[PrunletSparseE2E]::CaptureProof($alias);Assert-SparseProofR $sparse.proof $survivor 1;$read=[IO.File]::OpenRead($alias);try{$bytes=[byte[]]::new($sparse.prefix.Length);$read.ReadExactly($bytes);Assert-R ([Convert]::ToBase64String($bytes)-ceq[Convert]::ToBase64String($sparse.prefix)) 'Surviving hardlink contents changed'}finally{$read.Dispose()};$script:observed.survivingAlias=$survivor}
  else{$null=Restore-BinR $s $ordinary $normalBefore $normalPrior}
  No-FileRecordsR $s
 }catch{$script:observed.bodyError=$_.Exception.ToString();throw}finally{
  if($session){Close-McpR $session}
  if($ordinary-and!$tree-and!(Test-Path -LiteralPath $ordinary)){$new=@([Prunlet.RecordlessE2E.OwnedBinLocator]::FindIdentity($normalBefore[0].Id)|Where-Object {$_.Pidl-notin$normalPrior});if($new.Count-eq1){$null=Restore-BinR $s $ordinary $normalBefore $normalPrior}elseif($new.Count-gt1){throw 'Multiple ordinary Bin entries; fixture retained'}}
  Finish-OversizeR $s $sparse $root $rootId $rootPrior $alias $members
 }
}
function Test-OversizeAliasBatchR([switch]$Tree) {
 Initialize-SparseR;$s=New-ScopeR $(if($Tree){'oversize-alias-tree'}else{'oversize-alias-batch'});$root=if($Tree){Join-Path $s.files 'tree'}else{$s.files};if($Tree){$null=[IO.Directory]::CreateDirectory($root)};$first=Join-Path $root 'first';$second=Join-Path $root 'second';$survivor=Join-Path $root 'survivor';$sparse=New-OversizeR $first;$aliases=if($Tree){@($first,$second)}else{@($first,$second,$survivor)};$rootId=if($Tree){[Prunlet.RecordlessE2E.FixtureNative]::Identity($root)}else{''};$rootPrior=if($Tree){[string[]]@([Prunlet.RecordlessE2E.OwnedBinLocator]::FindIdentity($rootId)|ForEach-Object Pidl)}else{@()}
 try{
  [Prunlet.RecordlessE2E.FixtureNative]::CreateHardlink($second,$first);if(!$Tree){[Prunlet.RecordlessE2E.FixtureNative]::CreateHardlink($survivor,$first)};$sparse.proof=[PrunletSparseE2E]::CaptureProof($first);Assert-R ($sparse.proof.NumberOfLinks-eq$aliases.Count-and$sparse.proof.Length-eq$sparse.logical-and[PrunletSparseE2E]::Allocation($first)-le1MB) 'Hardlink sparse fixture invalid'
  $paths=if($Tree){@($root)}else{@($first,$second)};$expected=if($Tree){@('permanently_deleted')}else{@('permanently_deleted','permanently_deleted')};$dryStatuses=@($paths|ForEach-Object {'would_recycle'});$dry=Delete-R $s $paths -DryRun -Recursive:$Tree;$script:observed.dry=$dry;Assert-R ($dry.exitCode-eq0) 'Alias dry-run failed';Assert-WireR $dry $paths $dryStatuses $true;Assert-R (@($dry.json.warnings|Where-Object {$_-match'(?i)dry.run'-and$_-match'(?i)permanent'}).Count-gt0) 'Dry-run did not warn about permanent deletion'
  foreach($alias in $aliases){$proof=[PrunletSparseE2E]::CaptureProof($alias);Assert-SparseProofR $sparse.proof $proof $aliases.Count};Assert-NoNewBinR $sparse.proof.Id $sparse.prior;if($Tree){Assert-NoNewBinR $rootId $rootPrior}
  $result=Delete-R $s $paths -Recursive:$Tree;$script:observed.delete=$result;Assert-R ($result.exitCode-eq0) 'Alias deletion failed';Assert-WireR $result $paths $expected;Assert-R (!(Test-Path -LiteralPath $first)-and!(Test-Path -LiteralPath $second)) 'Deleted aliases remain';Assert-NoNewBinR $sparse.proof.Id $sparse.prior
  if($Tree){Assert-R (!(Test-Path -LiteralPath $root)) 'Oversized alias directory remains';Assert-NoNewBinR $rootId $rootPrior}else{$proof=[PrunletSparseE2E]::CaptureProof($survivor);Assert-SparseProofR $sparse.proof $proof 1;$read=[IO.File]::OpenRead($survivor);try{$bytes=[byte[]]::new($sparse.prefix.Length);$read.ReadExactly($bytes);Assert-R ([Convert]::ToBase64String($bytes)-ceq[Convert]::ToBase64String($sparse.prefix)) 'Surviving alias contents changed'}finally{$read.Dispose()};$script:observed.survivingAlias=$proof};No-FileRecordsR $s
 }catch{$script:observed.bodyError=$_.Exception.ToString();throw}finally{
  # 同一IDのBin項目から元の別名は特定できないため、自動復元や再送は行わない。
  $states=[Collections.Generic.List[object]]::new();$script:observed.aliasReconciliation=$states;$issues=[Collections.Generic.List[string]]::new();$remaining=[Collections.Generic.List[string]]::new();if($Tree){$rootBin=@([Prunlet.RecordlessE2E.OwnedBinLocator]::FindIdentity($rootId)|Where-Object {$_.Pidl-notin$rootPrior});$script:observed.aliasRootBin=$rootBin;if($rootBin.Count-eq1-and!(Test-Path -LiteralPath $root)){$null=[Prunlet.RecordlessE2E.FixtureNative]::RestoreOwned($rootBin[0].Pidl,$rootBin[0].PhysicalPath,$rootId,$root,$s.files)}elseif($rootBin.Count){$issues.Add('Directory Bin identity is ambiguous; retained')};if((Test-Path -LiteralPath $root)-and[Prunlet.RecordlessE2E.FixtureNative]::Identity($root)-cne$rootId){$issues.Add('Directory identity changed; retained')}};$newBin=@([Prunlet.RecordlessE2E.OwnedBinLocator]::FindIdentity($sparse.proof.Id)|Where-Object {$_.Pidl-notin$sparse.prior});$script:observed.aliasNewBin=$newBin
  foreach($alias in $aliases){$state=@{path=$alias;present=[IO.File]::Exists($alias)};$states.Add($state);if(!$state.present){continue};$remaining.Add($alias);try{$proof=[PrunletSparseE2E]::CaptureProof($alias);$state.proof=$proof;foreach($field in @('Id','SecurityBase64','Attributes','Length')){Assert-R ($proof.$field-ceq$sparse.proof.$field) ('Alias '+$field+' changed')};$read=[IO.File]::OpenRead($alias);try{$bytes=[byte[]]::new($sparse.prefix.Length);$read.ReadExactly($bytes);Assert-R ([Convert]::ToBase64String($bytes)-ceq[Convert]::ToBase64String($sparse.prefix)) 'Alias prefix changed'}finally{$read.Dispose()}}catch{$state.error=$_.Exception.ToString();$issues.Add(($alias+': '+$state.error))}}
  foreach($state in $states){if($state.present-and$state.proof-and$state.proof.NumberOfLinks-ne$remaining.Count){$issues.Add(($state.path+': link count differs from recorded aliases; retained'))}}
  if($newBin.Count){$issues.Add('New Bin entries share the alias ID; originals cannot be identified and are retained')}
  if($remaining.Count-gt1){$issues.Add('Multiple aliases remain; they are retained without resending deletion')}
  if(!$issues.Count-and$remaining.Count-eq1){Finish-OversizeR $s $sparse $remaining[0] $sparse.proof.Id $sparse.prior $remaining[0]}
  if($issues.Count){throw ('Alias batch reconciliation failed: '+($issues-join'; '))}
 }
}
function Test-OversizeCrossDirectoryAliasesR([switch]$Mcp,[ValidateSet('','rendezvous','child-race','locked-child','guard-probe','time-probe','external-change','external-attributes','external-masked-change')][string]$CoreMode=''){
 Initialize-SparseR;$s=New-ScopeR $(if($Mcp){'oversize-cross-directory-mcp'}elseif($CoreMode){'oversize-cross-directory-core-'+$CoreMode}else{'oversize-cross-directory-cli'});$roots=@((Join-Path $s.files 'second-root'),(Join-Path $s.files 'first-root'));$rootInfo=[Collections.Generic.List[object]]::new()
 foreach($root in $roots){$null=[IO.Directory]::CreateDirectory($root);$id=[Prunlet.RecordlessE2E.FixtureNative]::Identity($root);$rootInfo.Add(@{path=$root;id=$id;attributes=[int](Get-Item -LiteralPath $root -Force).Attributes;security=[Convert]::ToBase64String((Get-Acl -LiteralPath $root).GetSecurityDescriptorBinaryForm());prior=[string[]]@([Prunlet.RecordlessE2E.OwnedBinLocator]::FindIdentity($id)|ForEach-Object Pidl);sparsePath=(Join-Path $root 'huge-sparse');sparse=$null})}
 $survivor=File-R $s 'surviving-alias';$aliases=@($roots|ForEach-Object {$root=$_;0..31|ForEach-Object {Join-Path $root ('alias-'+$_.ToString('D2'))}})+@($survivor);$session=$null;$aliasBefore=$null;$aliasPrior=@()
 try{
  foreach($root in $rootInfo){$root.sparse=New-OversizeR $root.sparsePath;Assert-SparseProofR $root.sparse.proof ([PrunletSparseE2E]::CaptureProof($root.sparsePath)) 1;$read=[IO.File]::OpenRead($root.sparsePath);try{$bytes=[byte[]]::new($root.sparse.prefix.Length);$read.ReadExactly($bytes);Assert-R ([Convert]::ToBase64String($bytes)-ceq[Convert]::ToBase64String($root.sparse.prefix)) 'Sparse prefix changed'}finally{$read.Dispose()}}
  if($CoreMode-in@('external-change','external-masked-change')){[IO.File]::WriteAllText(($survivor+':prunlet-external-probe'),'owned probe stream')}
  $aliasBefore=Snapshot-R $survivor;$aliasPrior=Before-BinR $aliasBefore;foreach($alias in $aliases){if($alias-cne$survivor){[Prunlet.RecordlessE2E.FixtureNative]::CreateHardlink($alias,$survivor)}};$aliasBefore=Snapshot-R $survivor;Assert-R ($aliases.Count-eq65-and$aliasBefore[0].NumberOfLinks-eq65) 'Cross-directory shared alias fixture invalid';foreach($alias in $aliases){$null=Assert-SnapshotR $alias $aliasBefore}
  $script:observed.fixture=@{roots=@($rootInfo);aliases=$aliases;alias=$aliasBefore;aliasPrior=$aliasPrior}
  if($Mcp){$session=Open-McpR $s;Init-McpR $session;$dry=Call-McpR $session 2 'delete_files' @{paths=@($roots);dryRun=$true;recursive=$true};Assert-R (!$dry.failed) 'MCP cross-directory dry-run failed'}else{$dry=Delete-R $s $roots -DryRun -Recursive;Assert-R ($dry.exitCode-eq0) 'CLI cross-directory dry-run failed'}
  $script:observed.dry=$dry;Assert-WireR $dry $roots @('would_recycle','would_recycle') $true
  foreach($root in $rootInfo){Assert-R ([Prunlet.RecordlessE2E.FixtureNative]::Identity($root.path)-ceq$root.id-and[int](Get-Item -LiteralPath $root.path -Force).Attributes-eq$root.attributes-and[Convert]::ToBase64String((Get-Acl -LiteralPath $root.path).GetSecurityDescriptorBinaryForm())-ceq$root.security) 'Dry-run changed root identity or security';Assert-SparseProofR $root.sparse.proof ([PrunletSparseE2E]::CaptureProof($root.sparsePath)) 1;$read=[IO.File]::OpenRead($root.sparsePath);try{$bytes=[byte[]]::new($root.sparse.prefix.Length);$read.ReadExactly($bytes);Assert-R ([Convert]::ToBase64String($bytes)-ceq[Convert]::ToBase64String($root.sparse.prefix)) 'Dry-run changed sparse prefix'}finally{$read.Dispose()};Assert-NoNewBinR $root.id $root.prior;Assert-NoNewBinR $root.sparse.proof.Id $root.sparse.prior};foreach($alias in $aliases){$null=Assert-SnapshotR $alias $aliasBefore};Assert-NoNewBinR $aliasBefore[0].Id $aliasPrior
  if($CoreMode){
   $result=& $rendezvousHost -AssemblyPath $AssemblyPath -ExpectedAssemblySha256 $ExpectedAssemblySha256 -ConfigPath $s.config -TargetPaths $roots -Mode $CoreMode
   $script:observed.coreRendezvous=$result
   Assert-R ($result.checkpointCount-eq2-and!$result.failure) 'Real Shell oversized checkpoints did not both arrive'
   if($CoreMode-eq'locked-child'){
    Assert-R ($result.lockAcquired-and$result.lockReleased-and$result.reportedError-and$result.result.Items.Count-eq2) 'Locked-child fixture or non-success missing'
    Assert-R ($result.result.Items[0].Status-ceq'ambiguous'-and$result.result.Items[1].Status-ceq'permanently_deleted') 'Failure did not release gate for independent root'
    Assert-R ([IO.Directory]::Exists($roots[0])-and![IO.Directory]::Exists($roots[1])) 'Failure/success roots mismatch'
