 Case-R 'cli-mcp-lock-over-sixty-seconds-progress-eof' {
  $s=New-ScopeR 'long-lock';$paths=@((File-R $s 'cli'),(File-R $s 'mcp'));$proofs=@($paths|ForEach-Object {,(Snapshot-R $_)});$priors=@($proofs|ForEach-Object {,(Before-BinR $_)});$pathFile=Join-Path $s.root 'cli-paths.json';Save-R $pathFile @($paths[0]);$mcp=Open-McpR $s;Init-McpR $mcp;$cli=$null;$held=$null;$messages=[Collections.Generic.List[object]]::new()
  try{
   $held=[IO.FileStream]::new((Join-Path $s.metadata 'maintenance.lock'),[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);$clock=[Diagnostics.Stopwatch]::StartNew();$cli=Start-R $ExecutablePath $s.config @('delete','--paths-file',$pathFile)
   $request=@{jsonrpc='2.0';id=10;method='tools/call';params=@{name='delete_files';arguments=@{paths=@($paths[1])};_meta=@{progressToken='recordless-lock-token'}}};$mcp.process.StandardInput.WriteLine(($request|ConvertTo-Json -Depth 10 -Compress));$mcp.process.StandardInput.Flush();$lineTask=$mcp.process.StandardOutput.ReadLineAsync()
   while($clock.ElapsedMilliseconds-lt65000){if($lineTask.IsCompleted){$line=$lineTask.GetAwaiter().GetResult();Assert-R ($null-ne$line) 'MCP ended during exclusive wait';$message=$line|ConvertFrom-Json -AsHashtable -Depth 50;$messages.Add($message);Assert-R (!$message.ContainsKey('id')) 'MCP responded before exclusive lock release';Assert-R ($message.method-ceq'notifications/progress'-and$message.params.progressToken-ceq'recordless-lock-token') 'Unexpected wait notification/token';$lineTask=$mcp.process.StandardOutput.ReadLineAsync()};Assert-R (!$cli.process.HasExited) 'CLI ended during exclusive wait';[Threading.Thread]::Sleep(25)}
   $script:observed.lockHeldMilliseconds=$clock.ElapsedMilliseconds;$held.Dispose();$held=$null;$reply=Finish-R $cli;$cli=$null;Assert-WireR $reply @($paths[0]) @('recycled');Assert-R ($reply.exitCode-eq0-and$reply.stderr.Length-gt0) 'CLI wait lacked stderr progress or success';$mcp.process.StandardInput.Close();$final=$false
   while($true){Assert-R ($lineTask.Wait(60000)) 'MCP EOF drain timeout';$line=$lineTask.GetAwaiter().GetResult();if($null-eq$line){break};$message=$line|ConvertFrom-Json -AsHashtable -Depth 50;$messages.Add($message);if($message.ContainsKey('id')){Assert-R (!$final-and$message.id-eq10-and!$message.result.isError) 'MCP final response invalid';$wire=$message.result.content[0].text|ConvertFrom-Json -AsHashtable -Depth 30;Assert-WireR @{json=$wire} @($paths[1]) @('recycled');$final=$true}else{Assert-R (!$final-and$message.method-ceq'notifications/progress'-and$message.params.progressToken-ceq'recordless-lock-token') 'Unexpected token or progress after final response'};$lineTask=$mcp.process.StandardOutput.ReadLineAsync()}
   Assert-R ($final-and@($messages|Where-Object method -CEQ 'notifications/progress').Count-ge2) 'MCP progress/final evidence missing';$script:observed.messages=@($messages);$script:observed.cli=$reply;Close-McpR $mcp;$mcp=$null
   foreach($i in 0..1){$null=Restore-BinR $s $paths[$i] $proofs[$i] $priors[$i]}
  }finally{if($held){$held.Dispose()};if($cli){$null=Finish-R $cli};if($mcp){Close-McpR $mcp}}
 }
