 foreach($tokenCase in @('number','absent')){
  Case-R "mcp-short-lock-$tokenCase" {
   $s=New-ScopeR ('short-lock-'+$tokenCase);$p=File-R $s 'source';$before=Snapshot-R $p;$prior=Before-BinR $before;$script:observed.original=$before;$script:observed.priorBin=$prior;$mcp=Open-McpR $s;Init-McpR $mcp;$held=$null;$messages=[Collections.Generic.List[object]]::new()
   try{
    $held=[IO.FileStream]::new((Join-Path $s.metadata 'maintenance.lock'),[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)
    $params=@{name='delete_files';arguments=@{paths=@($p)}};if($tokenCase-ceq'number'){$params._meta=@{progressToken=[long]123}}
    $request=@{jsonrpc='2.0';id=10;method='tools/call';params=$params};$mcp.process.StandardInput.WriteLine(($request|ConvertTo-Json -Depth 10 -Compress));$mcp.process.StandardInput.Flush();$pending=$mcp.process.StandardOutput.ReadLineAsync()
    $clock=[Diagnostics.Stopwatch]::StartNew();while($clock.ElapsedMilliseconds-lt10000){if($pending.IsCompleted){$line=$pending.GetAwaiter().GetResult();Assert-R ($null-ne$line) 'MCP ended during lock wait';$message=$line|ConvertFrom-Json -AsHashtable -Depth 50;Assert-R (!$message.ContainsKey('id')) 'MCP responded before lock release';$messages.Add($message);$pending=$mcp.process.StandardOutput.ReadLineAsync()};[Threading.Thread]::Sleep(25)}
    $held.Dispose();$held=$null;$mcp.process.StandardInput.Close();$final=$false
    while($true){Assert-R ($pending.Wait(30000)) 'MCP EOF drain timeout';$line=$pending.GetAwaiter().GetResult();if($null-eq$line){break};$message=$line|ConvertFrom-Json -AsHashtable -Depth 50;$messages.Add($message);if($message.ContainsKey('id')){Assert-R (!$final-and$message.id-eq10-and!$message.result.isError) 'MCP final response invalid';$wire=$message.result.content[0].text|ConvertFrom-Json -AsHashtable -Depth 30;Assert-WireR @{json=$wire} @($p) @('recycled');$final=$true}else{Assert-R (!$final) 'MCP sent progress after final response'};$pending=$mcp.process.StandardOutput.ReadLineAsync()}
    $stderr=$mcp.stderr.GetAwaiter().GetResult();$lines=@($stderr -split '\r?\n'|Where-Object {$_-cne''});$script:observed.messages=@($messages);$script:observed.stderr=$lines;$waiting=@($lines|Where-Object {$_-cmatch '^\[prunlet\] Waiting for recovery lock \([0-9]+\.[0-9]s elapsed\)\.$'});$acquired=@($lines|Where-Object {$_-cmatch '^\[prunlet\] Recovery lock acquired after [0-9]+\.[0-9]s\.$'});Assert-R ($waiting.Count-ge2-and$acquired.Count-eq1-and$lines.Count-eq$waiting.Count+1-and$lines[-1]-ceq$acquired[0]) 'Lock stderr sequence missing or unexpected'
    $notifications=@($messages|Where-Object {!$_.ContainsKey('id')});Assert-R ($final-and$messages.Count-eq$notifications.Count+1) 'Unexpected MCP response count'
    if($tokenCase-ceq'absent'){Assert-R ($notifications.Count-eq0) 'Progress without token'}else{Assert-R ($notifications.Count-eq$lines.Count) 'Progress and stderr count differ';$previous=0;for($i=0;$i-lt$notifications.Count;$i++){$n=$notifications[$i];Assert-R ($n.jsonrpc-ceq'2.0'-and$n.method-ceq'notifications/progress'-and$n.params.progressToken.GetType()-eq[long]-and$n.params.progressToken-eq123) 'Progress token value or type changed';Assert-R ($n.params.progress-gt$previous-and!$n.params.ContainsKey('total')-and$n.params.message-ceq$lines[$i]) 'Progress order, total, or message differs';$previous=$n.params.progress}}
    $script:observed.messages=@($messages);$script:observed.stderr=$lines;Close-McpR $mcp;$mcp=$null;$null=Restore-BinR $s $p $before $prior
   }finally{if($held){$held.Dispose()};if($mcp){Close-McpR $mcp}}
  }
 }
 foreach($dllMode in @('released','held','mcp-held')){
  $heldDll=$dllMode-ne'released';$caseName=if($dllMode-eq'mcp-held'){'mcp-loaded-dll-held'}elseif($heldDll){'cli-loaded-dll-held'}else{'cli-loaded-dll-released'}
